    (113, "وَقَالَتِ الْيَهُودُ لَيْسَتِ النَّصَارَىٰ عَلَىٰ شَيْءٍ وَقَالَتِ النَّصَارَىٰ لَيْسَتِ الْيَهُودُ عَلَىٰ شَيْءٍ وَهُمْ يَتْلُونَ الْكِتَابَ ۗ كَذَٰلِكَ قَالَ الَّذِينَ لَا يَعْلَمُونَ مِثْلَ قَوْلِهِمْ ۚ فَاللَّهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ",
        "یهودیان گفتند: «مسیحیان هیچ موقعیتى (نزد خدا) ندارند»، و مسیحیان نیز گفتند: «یهودیان هیچ موقعیتى ندارند (و بر باطلند)»:در حالى که هر دو دسته، کتاب خدا را مى خوانند (و باید از این گونه تعصبها برکنار باشند). افراد نادان (دیگر، همچون مشرکان نیز)، سخنى همانند سخن آنها داشتند! خداوند، روز قیامت، درباره آنچه در آن اختلاف داشتند، میان آنها داورى مى کند."),
    (114, "وَمَنْ أَظْلَمُ مِمَّن مَّنَعَ مَسَاجِدَ اللَّهِ أَن يُذْكَرَ فِيهَا اسْمُهُ وَسَعَىٰ فِي خَرَابِهَا ۚ أُولَٰئِكَ مَا كَانَ لَهُمْ أَن يَدْخُلُوهَا إِلَّا خَائِفِينَ ۚ لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ",
        "کیست ستمکارتر از آن کس که از بردن نام خدا در مساجد او جلوگیرى کرد و سعى در ویرانى آنها نمود؟! چنین کسانى نمى توانند، جز با ترس و وحشت، وارد این (کانونهاى عبادت) شوند. بهره آنها در دنیا رسوایى است و در آخرت، عذاب عظیم (الهى)!"),
    (115, "وَلِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ ۚ فَأَيْنَمَا تُوَلُّوا فَثَمَّ وَجْهُ اللَّهِ ۚ إِنَّ اللَّهَ وَاسِعٌ عَلِيمٌ",
        "مشرق و مغرب، از آن خداست! پس به هر سو رو کنید، رو به خدا کرده اید. خداوند داراى قدرت وسیع و (به همه چیز) داناست."),
    (116, "وَقَالُوا اتَّخَذَ اللَّهُ وَلَدًا ۗ سُبْحَانَهُ ۖ بَل لَّهُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ ۖ كُلٌّ لَّهُ قَانِتُونَ",
        "و (کافران) گفتند: «خداوند، فرزندى براى خود انتخاب کرده است». ـ منزّه است او ـ بلکه آنچه در آسمانها و زمین است، از آن اوست: و همه در برابر او خاضعند."),
    (117, "بَدِيعُ السَّمَاوَاتِ وَالْأَرْضِ ۖ وَإِذَا قَضَىٰ أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ",
        "پدید آورنده آسمانها و زمین اوست! و هنگامى که فرمان وجود چیزى را صادر کند، تنها مى گوید: «موجود باش!» و آن، (چیز، بى درنگ) موجود مى شود."),
    (118, "وَقَالَ الَّذِينَ لَا يَعْلَمُونَ لَوْلَا يُكَلِّمُنَا اللَّهُ أَوْ تَأْتِينَا آيَةٌ ۗ كَذَٰلِكَ قَالَ الَّذِينَ مِن قَبْلِهِم مِّثْلَ قَوْلِهِمْ ۘ تَشَابَهَتْ قُلُوبُهُمْ ۗ قَدْ بَيَّنَّا الْآيَاتِ لِقَوْمٍ يُوقِنُونَ",
        "افراد ناآگاه گفتند: «چرا خدا با ما سخن نمى گوید؟! و یا چرا نشانه اى براى (خود) ما نمى آید؟!» پیشینیان آنها نیز، همین گونه سخن مى گفتند: دلها و افکارشان مشابه یکدیگر است: ولى ما (به اندازه کافى) آیات و نشانه ها را براى اهل یقین (و حقیقت جویان) روشن ساخته ایم."),
    (119, "إِنَّا أَرْسَلْنَاكَ بِالْحَقِّ بَشِيرًا وَنَذِيرًا ۖ وَلَا تُسْأَلُ عَنْ أَصْحَابِ الْجَحِيمِ",
        "ما تو را به حق، براى بشارت و بیم دادن (همه مردم) فرستادیم: و تو مسئول (گمراهى) دوزخیان (پس از ابلاغ رسالت) نیستى."),
    (120, "وَلَن تَرْضَىٰ عَنكَ الْيَهُودُ وَلَا النَّصَارَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمْ ۗ قُلْ إِنَّ هُدَى اللَّهِ هُوَ الْهُدَىٰ ۗ وَلَئِنِ اتَّبَعْتَ أَهْوَاءَهُم بَعْدَ الَّذِي جَاءَكَ مِنْ الْعِلْمِ ۙ مَا لَكَ مِنْ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ",
        "هرگز یهود و نصارى از تو راضى نخواهند شد، تا (به طور کامل تسلیم خواسته هاى آنها شوى، و) از آیین (تحریف یافته) آنان، پیروى کنى. بگو: «هدایت واقعى، هدایت خدا است.» واگر از هوا و هوسهاى آنان پیروى کنى، بعد از آن که آگاه شده اى، هیچ سرپرست و یاورى از سوى خدا براى تو نخواهد بود."),
    (121, "الَّذِينَ آتَيْنَاهُمُ الْكِتَابَ يَتْلُونَهُ حَقَّ تِلَاوَتِهِ أُولَٰئِكَ يُؤْمِنُونَ بِهِ ۗ وَمَن يَكْفُرْ بِهِ فَأُولَٰئِكَ هُمُ الْخَاسِرُونَ",
        "کسانى که کتاب آسمانى به آنها داده ایم [= یهود و نصارى ]و آن را چنان که شایسته آن است مى خوانند (و عمل مى کنند): آنها به پیامبر اسلام ایمان مى آورند: و کسانى که به او کافر شوند، زیانکارند."),
    (122, "يَا بَنِي إِسْرَائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَالَمِينَ",
        "اى بنى اسرائیل! نعمتم را، که به شما ارزانى داشتم، و شما را بر جهانیان برترى بخشیدم به یاد آورید."),
    (123, "وَاتَّقُوا يَوْمًا لَّا تَجْزِي نَفْسٌ عَن نَّفْسٍ شَيْئًا وَلَا يُقْبَلُ مِنْهَا عَدْلٌ وَلَا تَنفَعُهَا شَفَاعَةٌ وَلَا هُمْ يُنصَرُونَ",
        "و از روزى بترسید که کسى مجازات دیگرى را نمى پذیرد: و هیچ گونه غرامتى از او قبول نمى شود: و شفاعتى، او را سود نمى دهد: و (به هیچ صورت) یارى نخواهند شد."),
    (124, "۞ وَإِذِ ابْتَلَىٰ إِبْرَاهِيمَ رَبُّهُ بِكَلِمَاتٍ فَأَتَمَّهُنَّ ۖ قَالَ إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامًا ۖ قَالَ وَمِن ذُرِّيَّتِي ۖ قَالَ لَا يَنَالُ عَهْدِي الظَّالِمِينَ",
        "و (یاد کنید) هنگامى که پروردگار ابراهیم، او را با دستوراتى آزمود: و او به طور کامل از عهده آنها برآمد. خداوند به او فرمود: «من تو را امام و پیشواى مردم قرار دادم.» ابراهیم گفت: «از دودمان من (نیز امامانى قرار بده)» خداوند فرمود: «پیمان من، به ستمکاران نمى رسد (مگر آنها که شایسته اند)»."),
    (125, "وَإِذْ جَعَلْنَا الْبَيْتَ مَثَابَةً لِّلنَّاسِ وَأَمْنًا وَاتَّخِذُوا مِن مَّقَامِ إِبْرَاهِيمَ مُصَلًّى ۖ وَعَهَدْنَا إِلَىٰ إِبْرَاهِيمَ وَإِسْمَاعِيلَ أَن طَهِّرَا بَيْتِيَ لِلطَّائِفِينَ وَالْعَاكِفِينَ وَالرُّكَّعِ السُّجُودِ",
        "و (به یاد آورید) هنگامى که خانه کعبه را محل بازگشت (و اجتماع) مردم و مرکز امن قرار دادیم. و (به مردم گفتیم:) از مقام ابراهیم، عبادتگاهى براى خود انتخاب کنید. و از ابراهیم و اسماعیل پیمان گرفتیم که: «خانه مرا براى طواف کنندگان و مجاوران و رکوع کنندگان سجده گزار [= نماز گزاران]پاکیزه سازید.»"),
    (126, "وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَٰذَا بَلَدًا آمِنًا وَارْزُقْ أَهْلَهُ مِنَ الثَّمَرَاتِ مَنْ آمَنَ مِنْهُم بِاللَّهِ وَالْيَوْمِ الْآخِرِ ۖ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُ قَلِيلًا ثُمَّ أَضْطَرُّهُ إِلَىٰ عَذَابِ النَّارِ ۖ وَبِئْسَ الْمَصِيرُ",
        "و (به یاد آورید) هنگامى را که ابراهیم گفت: «پروردگارا! این سرزمین را شهر امنى قرار ده: و اهل آن را ـ آنها که به خدا و روز بازپسین، ایمان آورده اند ـ از ثمرات (گوناگون)، روزى ده.» فرمود: «(خواسته ات را پذیرفتم) و به هرکس که کافر شود، بهره اندکى خواهم داد: سپس آنها را به عذاب دوزخ مى کشانم: و چه بد فرجامى است!»"),
    (127, "وَإِذْ يَرْفَعُ إِبْرَاهِيمُ الْقَوَاعِدَ مِنَ الْبَيْتِ وَإِسْمَاعِيلُ رَبَّنَا تَقَبَّلْ مِنَّا ۖ إِنَّكَ أَنتَ السَّمِيعُ الْعَلِيمُ",
        "(و نیز به یاد آورید) هنگامى را که ابراهیم و اسماعیل، پایه:هاى خانه (کعبه) را بالا مى:بردند: (و مى:گفتند:) :پروردگارا! از ما بپذیر، که تو شنوا و دانائى"),
    (128, "رَبَّنَا وَاجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَا أُمَّةً مُّسْلِمَةً لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَا ۖ إِنَّكَ أَنتَ التَّوَّابُ الرَّحِيمُ",
        "پروردگارا! ما را تسلیم (فرمان) خود قرار ده: و از دودمان ما، امّتى که تسلیم (فرمان) تو باشند، به وجود آور: و شیوه عبادتمان را به ما نشان دهو توبه ما را بپذیر، که تویى توبه پذیر مهربان."),
    (129, "رَبَّنَا وَابْعَثْ فِيهِمْ رَسُولًا مِّنْهُمْ يَتْلُو عَلَيْهِمْ آيَاتِكَ وَيُعَلِّمُهُمُ الْكِتَابَ وَالْحِكْمَةَ وَيُزَكِّيهِمْ ۚ إِنَّكَ أَنتَ الْعَزِيزُ الْحَكِيمُ",
        "پروردگارا! پیامبرى در میان آنها از خودشان برانگیز، تا آیات تو را بر آنان بخواند، و آنها را کتاب و حکمت بیاموزد، و پاکیزه کند: زیرا تو تواناو حکیمى(وبر این کار، قادرى).»"),
    (130, "وَمَن يَرْغَبُ عَن مِّلَّةِ إِبْرَاهِيمَ إِلَّا مَن سَفِهَ نَفْسَهُ ۚ وَلَقَدِ اصْطَفَيْنَاهُ فِي الدُّنْيَا ۖ وَإِنَّهُ فِي الْآخِرَةِ لَمِنَ الصَّالِحِينَ",
        "جز افراد سفیه و نادان، چه کسى از آیین ابراهیم، (که آیین پاکى و یگانه پرستى است) روى گردان خواهد شد؟! ما او را در دنیا برگزیدیم: و او در آخرت، از صالحان است."),
    (131, "إِذْ قَالَ لَهُ رَبُّهُ أَسْلِمْ ۖ قَالَ أَسْلَمْتُ لِرَبِّ الْعَالَمِينَ",
        "(و یاد آورید) هنگامى را که پروردگارش به او فرمود: اسلام بیاور (و در برابر حق، تسلیم باش. او فرمان پروردگار را از جان و دل پذیرفت: و) گفت: «در برابر پروردگار جهانیان، تسلیم شدم.»"),
    (132, "وَوَصَّىٰ بِهَا إِبْرَاهِيمُ بَنِيهِ وَيَعْقُوبُ يَا بَنِيَّ إِنَّ اللَّهَ اصْطَفَىٰ لَكُمُ الدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ",
        "و ابراهیم و یعقوب (در واپسین لحظات عمر،) فرزندان خود را به این آیین، وصیّت کردند: (و هر کدام به فرزندان خویش گفتند:) «فرزندان من! خداوند این آیین (پاک) را براى شما برگزیده است: و شما، جز به آیین اسلام (و تسلیم در برابر فرمان خدا) از دنیا نروید.»"),
    (133, "أَمْ كُنتُمْ شُهَدَاءَ إِذْ حَضَرَ يَعْقُوبَ الْمَوْتُ إِذْ قَالَ لِبَنِيهِ مَا تَعْبُدُونَ مِن بَعْدِي قَالُوا نَعْبُدُ إِلَٰهَكَ وَإِلَٰهَ آبَائِكَ إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ إِلَٰهًا وَاحِدًا وَنَحْنُ لَهُ مُسْلِمُونَ",
        "آیا هنگامى که مرگ یعقوب فرا رسید، شما حاضر بودید؟! در آن هنگام که به فرزندان خود گفت: «پس از من، چه چیز را مى پرستید؟» گفتند: «خداى تو، و خداى پدرانت، ابراهیم و اسماعیل و اسحاق، خداى یگانه را، و ما در برابر او تسلیم هستیم.»"),
    (134, "تِلْكَ أُمَّةٌ قَدْ خَلَتْ ۖ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ ۖ وَلَا تُسْأَلُونَ عَمَّا كَانُوا يَعْمَلُونَ",
        "آنها امّتى بودند که درگذشتند. اعمال آنان، مربوط به خودشان بود و اعمال شما نیز مربوط به خود شماست: و شما مسؤول اعمال آنها نخواهید بود."),
    (135, "وَقَالُوا كُونُوا هُودًا أَوْ نَصَارَىٰ تَهْتَدُوا ۗ قُلْ بَلْ مِلَّةَ إِبْرَاهِيمَ حَنِيفًا ۖ وَمَا كَانَ مِنَ الْمُشْرِكِينَ",
        "(اهل کتاب) گفتند: «یهودى یا مسیحى شوید، تا هدایت یابید.» بگو: «(این آیینهاى تحریف شده و شرک آلود، هرگز نمى تواند موجب هدایت گردد،) بلکه از آیین ابراهیم، که ایمانى خالص داشت و از مشرکان نبود، پیروى کنید.»"),
